def transform(grid):
    h, w = len(grid), len(grid[0])
    # The divider is the uniform row that most evenly separates the grid.
    div = max(
        (r for r, row in enumerate(grid) if len(set(row)) == 1 and 0 < r < h - 1),
        key=lambda r: min(r, h - r - 1)
    )
    upper, lower = grid[:div], grid[div + 1:]

    def background(part):
        counts = {}
        for row in part:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        return max(counts, key=counts.get)

    bg1, bg2 = background(upper), background(lower)
    return [
        [3 if upper[r][c] != bg1 and lower[r][c] != bg2 else 0
         for c in range(w)]
        for r in range(min(len(upper), len(lower)))
    ]
